def group_tree(records):
    try:
        rows = list(records)
    except TypeError as exc:
        raise ValueError("records must be iterable") from exc

    by_id = {}
    normalized = []
    for row in rows:
        if not isinstance(row, dict) or set(row) != {"id", "parent", "label"}:
            raise ValueError("malformed record")
        ident, parent, label = row["id"], row["parent"], row["label"]
        if not isinstance(ident, str) or not ident or ident in by_id:
            raise ValueError("invalid id")
        if parent is not None and (not isinstance(parent, str) or not parent):
            raise ValueError("invalid parent")
        if not isinstance(label, str):
            raise ValueError("invalid label")
        item = (ident, parent, label)
        by_id[ident] = item
        normalized.append(item)

    if any(parent is not None and parent not in by_id for _, parent, _ in normalized):
        raise ValueError("unknown parent")
    for ident, _, _ in normalized:
        seen = set()
        current = ident
        while current is not None:
            if current in seen:
                raise ValueError("cycle")
            seen.add(current)
            current = by_id[current][1]

    children = {}
    for item in normalized:
        children.setdefault(item[1], []).append(item)

    def visit(parent, depth):
        siblings = children.get(parent, [])
        if not siblings:
            return []
        output = [{"depth": depth, "labels": [item[2] for item in siblings]}]
        descendants = []
        for ident, _, _ in siblings:
            descendants = visit(ident, depth + 1)
        output.extend(descendants)
        return output

    return visit(None, 0)
```

